// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategoryimport com.roshan.persona.system.util.HardwareExceptionMapper/** * NOUS — Torch Handler (Module 10 v2 — Step 10.3). * * Turns the device's camera flash on/off as a torch. Implements the full * v2 handler contract: idempotent execution, pre-state capture for undo, * thermal awareness, and hardware exception mapping. * * ## Behavior * *  - **[isAvailable]**: true iff the device has a back-facing camera with a *    flash unit. Devices without flash return `Result.Failure(Hardware.Unavailable)`. * *  - **[isAlreadyInTargetState]**: returns true if the torch is already in the *    target on/off state AND (for brightness adjustments) the current *    brightness matches the target. This skips redundant hardware calls *    (zero-flicker, battery save — Review 2 Elite 1). * *  - **[capturePreState]**: returns the previous torch state *    (`Pair<Boolean, Float>` — on/off + brightness). Used by undo to restore *    the exact previous state, not just "off" (Review 2 Fix A). * *  - **[execute]**: wraps `setTorchMode` in try-catch; `CameraAccessException` *    is mapped via [HardwareExceptionMapper] to `Hardware.InUse` (camera in *    use by another app) or `Hardware.Unavailable` (camera disconnected). * *  - **[restorePreState]**: turns the torch back on/off to the captured state. * * ## Brightness (API 33+) * * On Android 13+ (Tiramisu), the torch brightness can be controlled via * `setTorchModeStrengthLevel`. On older devices, the brightness parameter is * ignored (torch is either off or full brightness). * * ## Resource category * * Torch uses the camera resource (CameraManager) — categorized as [ResourceCategory.CAMERA]. * This means two torch operations in a batch run **sequentially** (same category) * to avoid CameraManager contention. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Privacy & Security — Hardware Exception Matrix</a> */class TorchHandler(    private val cameraService: CameraService,) : ReversibleHandler<SystemOperation.SetTorch> {    override val id: String = "torch"    override val displayName: String = "Torch Control"    override val requiredPermissions: Set<String> = setOf(android.Manifest.permission.CAMERA)    override val resourceCategory: ResourceCategory = ResourceCategory.CAMERA    override fun isAvailable(): Boolean = cameraService.hasTorch()    override suspend fun execute(operation: SystemOperation.SetTorch): Result<Unit> {        if (!isAvailable()) {            return Result.Failure(                error = com.roshan.persona.common.AppError.Hardware.Unavailable("torch"),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }        val cameraId = cameraService.getTorchCameraId()            ?: return Result.Failure(                error = com.roshan.persona.common.AppError.Hardware.Unavailable("torch"),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        return HardwareExceptionMapper.withMappingSync("torch") {            cameraService.setTorchMode(cameraId, operation.on)            // Brightness control (API 33+) — only when torch is on and brightness != 1.0.            if (operation.on && operation.brightness < 1.0f && cameraService.supportsBrightnessControl()) {                try {                    cameraService.setTorchBrightnessLevel(cameraId, operation.brightness)                } catch (t: UnsupportedOperationException) {                    // Brightness not supported on this device — torch is on at full brightness.                    Timber.tag("TorchHandler").d("Brightness control unsupported — torch at full brightness.")                }            }            Result.Success(Unit, CorrelationId.generate(), 0)        }    }    override suspend fun capturePreState(operation: SystemOperation.SetTorch): Any? {        val cameraId = cameraService.getTorchCameraId() ?: return null        val wasOn = try {            cameraService.isTorchEnabled(cameraId)        } catch (t: Throwable) {            false        }        return TorchPreState(wasOn = wasOn)    }    override suspend fun restorePreState(operation: SystemOperation.SetTorch, preState: Any?) {        if (preState !is TorchPreState) return        val cameraId = cameraService.getTorchCameraId() ?: return        try {            if (preState.wasOn != cameraService.isTorchEnabled(cameraId)) {                cameraService.setTorchMode(cameraId, preState.wasOn)            }        } catch (t: Throwable) {            Timber.tag("TorchHandler").w("Failed to restore torch state", t)        }    }    override suspend fun getCurrentState(): Any? {        val cameraId = cameraService.getTorchCameraId() ?: return null        return TorchPreState(wasOn = cameraService.isTorchEnabled(cameraId))    }    override suspend fun isAlreadyInTargetState(operation: SystemOperation.SetTorch): Boolean {        val cameraId = cameraService.getTorchCameraId() ?: return false        val currentOn = try {            cameraService.isTorchEnabled(cameraId)        } catch (t: Throwable) {            return false        }        // Idempotent: skip if already at target on/off state.        // (We don't check brightness — setTorchMode doesn't expose current brightness.)        return currentOn == operation.on    }    override fun describeOperation(operation: SystemOperation.SetTorch): String =        if (operation.on) "Torch turned on" else "Torch turned off"    // ─── Pre-state serialization (audit defect B fix) ─────────────────────    override fun serializePreState(preState: Any?): String? {        if (preState == null) return null        if (preState !is TorchPreState) {            return com.roshan.persona.system.undo.SystemOperationSerializer.serializePreState(preState)        }        return "{\"type\":\"TorchPreState\",\"wasOn\":${preState.wasOn}}"    }    override fun deserializePreState(json: String?): Any? {        if (json == null) return null        val map = try {            com.roshan.persona.system.undo.SystemOperationSerializer.parseJsonObject(json)        } catch (t: Throwable) {            return com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }        return when (map["type"] as? String) {            "TorchPreState" -> TorchPreState(wasOn = (map["wasOn"] as? Boolean) ?: false)            else -> com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }    }    /** Captured pre-state for torch (just on/off — brightness isn't readable). */    data class TorchPreState(val wasOn: Boolean)}
